	switch outcome, reason := p.refOutcome(name); outcome {
	case gitproto.RefOutcomeApplied:
		return true, ""
	case gitproto.RefOutcomeRefused:
		return false, reason
	case gitproto.RefOutcomeUnknown:
		return false, "target reported no status for this ref"
	default:
		return false, "target reported no status for this ref"
