package syncer

import (
	"context"
	"errors"
	"testing"

	git "github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/protocol/packp"
	"github.com/go-git/go-git/v6/storage/memory"

	"entire.io/entire/git-sync/internal/gitproto"
	"entire.io/entire/git-sync/internal/syncertest"
)

func hashOf(t *testing.T, repo *git.Repository, ref plumbing.ReferenceName) plumbing.Hash {
	t.Helper()
	r, err := repo.Reference(ref, false)
	if err != nil {
		return plumbing.ZeroHash
	}
	return r.Hash()
}

// A: rest = update + moved create + prune delete. What lands?
func TestAdv_MixedRest(t *testing.T) {
	sourceRepo, sourceFS := newSourceRepo(t)
	makeCommits(t, sourceRepo, sourceFS, 2)
	trunkRef := plumbing.NewBranchReferenceName(testBranch)
	trunk, err := sourceRepo.Reference(trunkRef, true)
	if err != nil {
		t.Fatal(err)
	}
	updRef := plumbing.NewBranchReferenceName("upd")
	goneRef := plumbing.NewBranchReferenceName("gone")
	syncertest.SetRefAtBranch(t, sourceRepo, updRef, testBranch)
	syncertest.SetRefAtBranch(t, sourceRepo, goneRef, testBranch)

	targetRepo, err := git.Init(memory.NewStorage())
	if err != nil {
		t.Fatal(err)
	}
	if err := copyRefsAndObjects(sourceRepo.Storer, targetRepo.Storer, []plumbing.ReferenceName{trunkRef, updRef, goneRef}); err != nil {
		t.Fatal(err)
	}
	if err := sourceRepo.Storer.RemoveReference(goneRef); err != nil {
		t.Fatal(err)
	}

	makeLargeCommits(t, sourceRepo, sourceFS, 4, 100_000)
	syncertest.SetRefAtBranch(t, sourceRepo, plumbing.NewBranchReferenceName("feature"), testBranch)
	makeCommits(t, sourceRepo, sourceFS, 1)
	xRef := plumbing.NewBranchReferenceName("x")
	xSource := syncertest.SetRefAtBranch(t, sourceRepo, xRef, testBranch)
	updSource := syncertest.SetRefAtBranch(t, sourceRepo, updRef, testBranch)
	if err := sourceRepo.Storer.SetReference(plumbing.NewHashReference(trunkRef, trunk.Hash())); err != nil {
		t.Fatal(err)
	}

	sourceServer := newSmartHTTPRepoServerV2(t, sourceRepo)
	targetServer := newSmartHTTPRepoServer(t, targetRepo)
	defer sourceServer.Close()
	defer targetServer.Close()
	writer := &concurrentRefWriter{ref: xRef}
	writer.install = func() {
		if err := targetRepo.Storer.SetReference(plumbing.NewHashReference(xRef, trunk.Hash())); err != nil {
			t.Errorf("install: %v", err)
		}
	}
	targetServer.receivePackBodyLimit = 300_000
	targetServer.receivePackRaw = writer.observe
	targetServer.receivePackUnpackForHook = true
	var requests [][]packp.Command
	targetServer.receivePackHook = func(req *packp.UpdateRequests, _ bool) *packp.ReportStatus {
		var cmds []packp.Command
		for _, c := range req.Commands {
			cmds = append(cmds, *c)
		}
		requests = append(requests, cmds)
		for _, cmd := range req.Commands {
			if cmd.Name == xRef && cmd.Old.IsZero() && !hashOf(t, targetRepo, xRef).IsZero() {
				return applyCommandsExcept(targetRepo.Storer, req, xRef, "already exists")
			}
		}
		return nil
	}

	result, err := Run(context.Background(), Config{
		Source: Endpoint{URL: sourceServer.RepoURL()}, Target: Endpoint{URL: targetServer.RepoURL()},
		Mode: modeReplicate, Prune: true, ProtocolMode: protocolModeAuto,
	})
	t.Logf("err=%v", err)
	t.Logf("isMoved=%v reason=%s", errors.Is(err, gitproto.ErrTargetRefMoved), result.RelayReason)
	for i, r := range requests {
		for _, c := range r {
			t.Logf("req %d: %s %s -> %s", i, c.Name, c.Old.String()[:7], c.New.String()[:7])
		}
	}
	t.Logf("x target=%s (other sync wrote %s, source %s)", hashOf(t, targetRepo, xRef), trunk.Hash(), xSource)
	t.Logf("upd target=%s source=%s applied=%v", hashOf(t, targetRepo, updRef), updSource, hashOf(t, targetRepo, updRef) == updSource)
	t.Logf("gone still on target=%v", !hashOf(t, targetRepo, goneRef).IsZero())
}

// B: same race as the PR test, but the caller opted into BestEffort.
func TestAdv_BestEffort(t *testing.T) {
