	var requests [][]packp.Command
	targetServer.receivePackHook = func(req *packp.UpdateRequests, _ bool) *packp.ReportStatus {
		var cmds []packp.Command
		for _, c := range req.Commands {
			cmds = append(cmds, *c)
		}
		requests = append(requests, cmds)
		for _, cmd := range req.Commands {
			if cmd.Name == xRef && cmd.Old.IsZero() && !hashOf(t, targetRepo, xRef).IsZero() {
				return applyCommandsExcept(targetRepo.Storer, req, xRef, "already exists")
			}
		}
		return nil
	}

	result, err := Run(context.Background(), Config{
		Source: Endpoint{URL: sourceServer.RepoURL()}, Target: Endpoint{URL: targetServer.RepoURL()},
		Mode: modeReplicate, Prune: true, ProtocolMode: protocolModeAuto,
	})
	t.Logf("err=%v", err)
	t.Logf("isMoved=%v reason=%s", errors.Is(err, gitproto.ErrTargetRefMoved), result.RelayReason)
	for i, r := range requests {
